SELECT titulo 
FROM libro l INNER JOIN prestamo p
ON  l.id_libro = p.id_libro
INNER JOIN estudiante e
ON e.id_lector = p.id_lector
WHERE e.nombre = "Ana";

SELECT * FROM estudiante
WHERE edad IN (SELECT MIN(edad) FROM estudiante);

