FROM libro l INNER JOIN prestamo p
ON  l.id_libro = p.id_libro
INNER JOIN estudiante e
ON e.id_lector = p.id_lector
WHERE l.area = "Literatura";

SELECT l.titulo 
FROM autor a INNER JOIN libro_autor la
ON  a.id_autor = la.id_autor
INNER JOIN libro l
ON l.id_libro = la.id_libro
WHERE a.nombre = "George Orwell";

